11	export function applyCredits(chargeCents, grants = [], asOfMs = 0) {
12	  if (!Number.isFinite(chargeCents)) {
13	    throw new LedgerError(ERROR_CODES.ERR_INVALID_AMOUNT, 'chargeCents must be finite');
14	  }
15	  if (!Array.isArray(grants)) {
16	    throw new LedgerError(ERROR_CODES.ERR_INVALID_CONFIG, 'grants must be an array');
17	  }
18	
19	  let remaining = chargeCents;
20	  let appliedCents = 0;
21	  const allocations = [];
22	
23	  for (const grant of grants) {
24	    if (remaining <= 0) break;
25	    if (!grant || grant.remainingCents <= 0) continue;
26	    const take = Math.min(remaining, grant.remainingCents);
27	    grant.remainingCents -= take;
28	    remaining -= take;
29	    appliedCents += take;
30	    allocations.push({ grantId: grant.grantId, appliedCents: take });
31	  }
32	
33	  return {
34	    appliedCents,
35	    remainingChargeCents: remaining,
36	    allocations,
37	    updatedGrants: grants
38	  };
39	}
